function batchForm(){return `<form id="batchForm" class="rx-form-grid"><div><label>Medicine</label><select id="bProduct" class="form-select" required><option value="">Select medicine…</option>${S.products.map(p=>`<option value="${esc(p.id)}">${esc(`${p.sku} — ${p.name}`)}</option>`).join("")}</select></div><div><label>Warehouse</label><select id="bWarehouse" class="form-select" required><option value="">Select warehouse…</option>${(S.salesContext.warehouses||[]).map(w=>`<option value="${esc(w.id)}">${esc(w.name)}</option>`).join("")}</select></div><div><label>Batch / lot</label><input id="bNo" class="form-control" required></div><div><label>Production date</label><input id="bProd" type="date" class="form-control"></div><div><label>Expiry date</label><input id="bExpiry" type="date" class="form-control" required></div><div><label>Quantity in base units</label><input id="bQty" type="number" min="0" step="0.001" class="form-control" required></div><div><label>Smallest unit</label><input id="bUnit" class="form-control" value="PCS"></div><div><label>Units per stock unit</label><input id="bMultiplier" type="number" min="0.0001" step="0.0001" class="form-control" value="1"></div><div class="wide"><button class="rx-btn rx-btn-primary" type="submit">Receive batch</button></div></form>`}
