function expiryRows(kind){return S.batches.filter(b=>{const d=daysTo(b.expiryDate),s=String(b.status).toLowerCase();if(kind==="near")return d!==null&&d>=0&&d<=90&&["available","near_expiry"].includes(s);if(kind==="expired")return d!==null&&d<0||["expired","quarantined","recalled"].includes(s);return d!==null&&d<=90||["expired","quarantined","recalled"].includes(s)}).sort((a,b)=>new Date(a.expiryDate)-new Date(b.expiryDate))}
