async function stockPage(){await Promise.all([products(),batches()]);const root=$("#pharmacyContent");root.innerHTML=hero("Stock & FEFO","Each medicine shows its saleable batches in first-expiry-first-out order.")+`<section class="rx-card mt-3"><div class="rx-toolbar"><input id="stockSearch" class="form-control" placeholder="Search medicine or batch"></div><div id="stockList" class="rx-stock-list"></div></section>`;const draw=()=>{const s=$("#stockSearch").value.toLowerCase();const rows=S.products.filter(p=>!s||[p.name,p.sku,p.brand,field(p,"genericName","")].join(" ").toLowerCase().includes(s)||S.batches.some(b=>b.productId===p.id&&b.batchNo.toLowerCase().includes(s)));$("#stockList").innerHTML=rows.map(p=>{const bs=S.batches.filter(b=>b.productId===p.id).sort((a,b)=>new Date(a.expiryDate)-new Date(b.expiryDate));return `<article class="rx-stock-card"><div><strong>${esc(p.name)}</strong><small>${esc(`${p.sku} · ${field(p,"genericName","")}`)}</small></div><div class="rx-stock-total">${esc(String(p.currentStock))} ${esc(p.unit||"PCS")}</div><div class="rx-batch-chips">${bs.length?bs.map((b,i)=>`<span class="${["available","near_expiry"].includes(b.status)&&daysTo(b.expiryDate)>=0?"saleable":"blocked"}">${i===0?"FEFO · ":""}${esc(b.batchNo)} · ${esc(date(b.expiryDate))} · ${esc(String(b.qtyOnHandBase))}</span>`).join(""):`<span class="blocked">No batch record</span>`}</div></article>`}).join("")||`<div class="rx-empty">No medicines found</div>`};$("#stockSearch").addEventListener("input",draw);draw()}
function addCart(p){let x=S.cart.find(i=>i.productId===p.id);if(x)x.qty++;else{const bs=saleableBatches(p.id),b=bs[0];if(cf(p).expiryTracking&&!b)return toast(`No saleable batch for ${p.name}`,"error");S.cart.push({productId:p.id,name:p.name,qty:1,rate:num(p.price),inventoryBatchId:b?.id||null})}drawCart()}function cartTotal(){return S.cart.reduce((s,i)=>s+i.qty*i.rate,0)}
