async function billingPage(){await Promise.all([sales(),customers()]);const root=$("#pharmacyContent"),id=qv("id"),selected=id?await apiGet(`/api/v1/sales-documents/${encodeURIComponent(id)}`).catch(()=>null):null;root.innerHTML=hero("Pharmacy Billing","Prescription-linked invoices and payment status.",link("pharmacy-terminal.html","New pharmacy sale","bi-capsule-pill"))+`<section class="rx-card mt-3">${table(["Invoice","Date","Customer","Payment","Total","Paid","Balance","Status","Action"],S.sales,r=>[r.documentNo,date(r.issuedAt),r.customerName||"Walk-in",r.paymentMethod,money(r.total),money(r.paid),money(r.balance),{html:badge(r.status)},{html:`<a class="rx-btn-soft" href="pharmacy-billing.html?id=${encodeURIComponent(r.id)}">View</a>`}],1000)}</section>${selected?`<section class="rx-card mt-3"><h3>${esc(selected.documentNo)}</h3>${table(["Medicine","Qty","Rate","Total"],selected.items||[],i=>[i.name,String(i.qty),money(i.rate),money(i.total)],600)}<div class="rx-invoice-total"><span>Total <strong>${money(selected.total)}</strong></span><span>Paid <strong>${money(selected.paid)}</strong></span><span>Balance <strong>${money(selected.balance)}</strong></span></div></section>`:""}`}
async function reportsPage(){await Promise.all([products(),batches(),prescriptions(),recalls(),sales(),suppliers()]);const root=$("#pharmacyContent"),near=expiryRows("near"),blocked=expiryRows("expired"),salesValue=S.sales.reduce((s,x)=>s+num(x.total),0),exposure=near.reduce((s,b)=>s+num(b.qtyOnHandBase)*num(productBy(b.productId)?.costPrice),0);root.innerHTML=hero("Pharmacy Reports","Operational summaries from medicine, batch, prescription, supplier and invoice records.")+`<div class="rx-grid rx-kpis">${kpi("Gross sales",money(salesValue),`${S.sales.length} invoices`)}${kpi("Prescription sales",S.sales.filter(x=>x.metadata?.prescriptionId).length,"Linked invoices")}${kpi("Near-expiry exposure",money(exposure),`${near.length} batches`)}${kpi("Blocked batches",blocked.length,"Expired/quarantined/recalled")}${kpi("Open recalls",S.recalls.filter(r=>r.status!=="closed").length,"Safety actions")}${kpi("Suppliers",S.suppliers.length,"Supplier master")}</div><div class="rx-two">${card("Expiry exposure by medicine","Cost-value estimate from available product cost",table(["Medicine","Batch count","Base qty","Exposure"],[...new Set(near.map(b=>b.productId))].map(id=>{const bs=near.filter(b=>b.productId===id),p=productBy(id);return{p,bs,qty:bs.reduce((s,b)=>s+num(b.qtyOnHandBase),0)}}),r=>[r.p?.name||"—",String(r.bs.length),r.qty.toFixed(2),money(r.qty*num(r.p?.costPrice))],650))}${card("Prescription status","Protected workflow counts",table(["Status","Count"],[...new Set(S.prescriptions.map(r=>r.status))].map(status=>({status,count:S.prescriptions.filter(r=>r.status===status).length})),r=>[{html:badge(r.status)},String(r.count)],400))}</div>`}
